#include <stdio.h>
#include <stdlib.h>
int cmp(const void*a,const void*b){return (*(long*)a>*(long*)b)-(*(long*)a<*(long*)b);}
int main(){int n;scanf("%d",&n);long*x=malloc(n*sizeof(long));for(int i=0;i<n;i++)scanf("%ld",&x[i]);qsort(x,n,sizeof(long),cmp);int m=1;for(int i=n-2;i>=0;i--){if(x[i]!=x[i+1]){printf("%ld\n",x[i]);return 0;}}printf("%ld\n",x[0]);return 0;}

